type TranslationDict = Record<TranslationKey, string>;
// New languages (ru/ar/zh) start with real translations for the highest-
// visibility, most-frequently-seen strings (nav, actions, auth, feed) and
// gracefully fall back to English for anything not yet translated - the
// runtime t() function already does this (translations[language]?.[key]
// ?? translations.en[key] ?? key), so this type just makes that
// intentional instead of accidentally missing. Existing languages
// (en/fr/de/it/es) remain fully populated in practice; this only relaxes
// what the type *requires*, not what they actually contain.
type PartialTranslationDict = Partial<TranslationDict>;

